package org.slavicmyths.skim;
import java.util.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.Monster;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.*;
import net.minecraft.world.damagesource.DamageSource;
public final class AlyoshaEntity extends SkimActor {
 private static final EntityDataAccessor<String> OWNER=SynchedEntityData.defineId(AlyoshaEntity.class,EntityDataSerializers.STRING);
 private static final EntityDataAccessor<Boolean> RECOVERING=SynchedEntityData.defineId(AlyoshaEntity.class,EntityDataSerializers.BOOLEAN);
 public UUID owner,arena;public boolean lastStand,intercepted;private Vec3 dodge,cover;private long daringUntil,lastHit;private int accurate,bowTicks,totalCombat;private UUID dodgedBoss;
 public AlyoshaEntity(EntityType<? extends AlyoshaEntity> t,Level w){super(t,w);}
 private int hurtVoiceVariation;
 @Override protected net.minecraft.sounds.SoundEvent getHurtSound(DamageSource source){return SkimContent.sound("alyosha.hurt_"+((hurtVoiceVariation++&1)+1));}
 @Override public void begin(SkimAction a){super.begin(a,(a==SkimAction.SABER||a==SkimAction.COUNTER)&&level().getGameTime()<daringUntil?(int)Math.ceil(a.ticks/1.1):a.ticks);}
 @Override protected EntityDimensions getDefaultDimensions(Pose p){return EntityDimensions.scalable(.72F,2.15F).withEyeHeight(1.9F);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(OWNER,"");b.define(RECOVERING,false);}
 public UUID syncedOwner(){try{return UUID.fromString(entityData.get(OWNER));}catch(Exception e){return null;}}public boolean recovering(){return lastStand||entityData.get(RECOVERING);}
 public SkimBeastEntity boss(){var v=arena!=null&&level() instanceof ServerLevel w?SkimValley.get(w).valleys.get(arena):null;return v!=null&&v.boss!=null&&((ServerLevel)level()).getEntity(v.boss) instanceof SkimBeastEntity b&&b.active()&&b.isAlive()?b:null;}
 public void bind(SkimValley.Entry v){arena=v.id;HeroCalls.recovered(this);lastStand=false;intercepted=false;accurate=0;bowTicks=totalCombat=0;setTarget(null);begin(SkimAction.IDLE);}
 public void retreat(){if(lastStand)return;if(!HeroCalls.beginRecovery(this)){HeroCalls.retire(this);return;}lastStand=true;entityData.set(RECOVERING,true);setTarget(null);var b=boss();if(b!=null){b.threat.remove(getUUID());var away=position().subtract(b.position()).multiply(1,0,1).normalize();if(away.lengthSqr()<.01)away=new Vec3(1,0,0);cover=org.slavicmyths.bogatyr.BogatyrLedger.safe((ServerLevel)level(),b.position().add(away.scale(22)),.72,2.15,3);}begin(SkimAction.RETREAT);HeroCalls.messageOwner(this,"alyosha.recovering");}
 public boolean evade(DamageSource s){if(action()==SkimAction.DODGE&&age()>=4&&age()<=7&&s.getDirectEntity() instanceof org.slavicmyths.kalin.KalinEntity&&s.is(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,org.slavicmyths.kalin.KalinContent.id("kalin_sabre"))))return true;return action()==SkimAction.DODGE&&age()>=4&&age()<=7&&s.getDirectEntity() instanceof SkimBeastEntity b&&(b.action()==SkimAction.CLAWS||b.action()==SkimAction.FLANK||b.action()==SkimAction.GRIP);}
 @Override public void tick(){super.tick();if(!(level() instanceof ServerLevel w)||!isAlive()||owner==null)return;entityData.set(OWNER,owner.toString());var d=HeroCalls.get(w);var id=d.alyosha.get(owner);if(id!=null&&!id.equals(getUUID())){discard();return;}if(id==null){d.alyosha.put(owner,getUUID());d.setDirty();}if(org.slavicmyths.kalin.KalinParty.prepare(this,owner))return;if(getPersistentData().getBoolean("HeroRecalling"))return;
  var p=w.getServer().getPlayerList().getPlayer(owner);var b=boss();if(arena!=null&&b==null){arena=null;if(lastStand&&getHealth()>=122.5){lastStand=false;HeroCalls.recovered(this);entityData.set(RECOVERING,false);begin(SkimAction.IDLE);}}
  if(getHealth()<=26.25&&!lastStand)retreat();if(lastStand){if(action()==SkimAction.RETREAT){if(cover!=null)getNavigation().moveTo(cover.x,cover.y,cover.z,1.2);if(age()>=25&&((b==null)||distanceToSqr(b)>=18*18)){begin(SkimAction.DRINK);cue("alyosha.drink_tonic");}else if(age()>=100&&b!=null){HeroCalls.sleep(this);return;}}else{if(tickCount%40==0&&getHealth()<122.5&&(b==null||distanceToSqr(b)>=18*18)){heal(Math.min(4,122.5F-getHealth()));begin(SkimAction.DRINK);cue("alyosha.drink_tonic");}if(action()==SkimAction.DRINK&&age()>=46)begin(SkimAction.REST);if(b==null&&getHealth()>=122.5){lastStand=false;HeroCalls.recovered(this);entityData.set(RECOVERING,false);begin(SkimAction.IDLE);}}return;}
  if(p==null||p.level()!=w){getNavigation().stop();setTarget(null);return;}if(b==null&&(org.slavicmyths.bogatyr.HeroThreats.activeStory(p)||org.slavicmyths.marinka.StoryPolicy.standby(owner,w))){getNavigation().stop();setTarget(null);return;}
  if(b!=null&&b.held()==this){getNavigation().stop();setTarget(null);begin(SkimAction.REST);return;}if(!lastStand&&action()==SkimAction.REST)begin(SkimAction.IDLE);
  var kb=org.slavicmyths.kalin.KalinParty.commander(this);if(kb!=null&&tickCount%5==0&&ready("dodge")&&action()==SkimAction.IDLE&&kb.action()==org.slavicmyths.finist.FalconAction.SWORD&&kb.age()<10&&edge(kb)<6&&planDodge(w)){cooldown("dodge",100);begin(SkimAction.DODGE);cue("alyosha.dodge_swish_1");}
  if(b!=null){totalCombat++;if(action()==SkimAction.BOW)bowTicks++;if(tickCount%5==0&&b.heavy()&&b.getTarget()==this&&action()!=SkimAction.DODGE&&ready("dodge")&&edge(b)>=2&&edge(b)<=9&&((b.action()==SkimAction.LEAP&&b.age()>=12&&b.age()<=20)||(b.action()!=SkimAction.LEAP&&b.age()<15))&&planDodge(w)){cooldown("dodge",36);dodgedBoss=b.getUUID();begin(SkimAction.DODGE);cue("alyosha.dodge_swish_"+(random.nextBoolean()?1:2));}}step(w,b);if(duration()>0&&age()>=duration()){if(action()==SkimAction.DODGE&&b!=null&&dodgedBoss!=null&&ready("counter")&&edge(b)<3&&b.landing().distSqr(blockPosition())>9){cooldown("counter",100);begin(SkimAction.COUNTER);b.addThreat(this,12);}else begin(SkimAction.IDLE);}if(action()!=SkimAction.IDLE)return;
  if(tickCount%10!=0)return;LivingEntity target=b!=null?b:org.slavicmyths.bogatyr.HeroThreats.nearest(this,p,14);var kalinTarget=org.slavicmyths.kalin.KalinParty.target(this,p);if(kalinTarget!=null)target=kalinTarget;setTarget(target);
  if(target==null){if(distanceToSqr(p)>49)getNavigation().moveTo(p,1);if(arena==null&&distanceToSqr(p)>900&&tickCount%60==0){var at=org.slavicmyths.bogatyr.BogatyrLedger.safe(w,p.position(),.72,3,3);if(at!=null)teleportTo(at.x,at.y,at.z);}return;}face(target);
  if(b!=null&&b.held()==p&&distanceToSqr(b)<64&&ready("rescue")){if(edge(b)>2.5){getNavigation().moveTo(b,1.3);return;}cooldown("rescue",100);begin(SkimAction.SABER);return;}

  if(ready("taunt")&&edge(target)<14&&hasLineOfSight(target)){cooldown("taunt",240);begin(SkimAction.TAUNT);return;}
  if(edge(target)<=2.5&&ready("saber")){cooldown("saber",76);begin(SkimAction.SABER);return;}if(edge(target)>=2&&edge(target)<=4.5&&ready("feint")){cooldown("feint",160);begin(SkimAction.FEINT);cue("alyosha.feint");return;}
  if(edge(target)>=6&&edge(target)<=18&&ready("bow")&&hasLineOfSight(target)&&(b==null||bowTicks+35<Math.max(240,totalCombat)*.15)){cooldown("bow",200);begin(SkimAction.BOW);cue("alyosha.bow_draw");return;}
  if(b!=null&&b.action()==SkimAction.EXHAUSTED){var opposite=b.position().subtract(p.position()).multiply(1,0,1).normalize().scale(4).add(b.position());getNavigation().moveTo(opposite.x,opposite.y,opposite.z,1.1);}else org.slavicmyths.poloz.PolozAim.navigate(this,target,w.getGameTime()<daringUntil?1.12:1);
  if(tickCount%16==0&&getDeltaMovement().horizontalDistanceSqr()>.0004)cue("alyosha.footstep_soft_"+(random.nextBoolean()?1:2));
 }
 private boolean planDodge(ServerLevel w){var side=new Vec3(heading().z,0,-heading().x);for(int sign:new int[]{random.nextBoolean()?1:-1,1,-1}){boolean safe=true;for(int i=1;i<=6;i++){var shift=side.scale(sign*i*.45);var q=net.minecraft.core.BlockPos.containing(position().add(shift));if(!w.hasChunkAt(q)||!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,q.below())||!w.noCollision(this,getBoundingBox().move(shift))){safe=false;break;}}if(safe){dodge=side.scale(sign*.45);return true;}}return false;}
 private void strike(float raw,SkimBeastEntity b){var t=getTarget();if(t!=null&&t.isAlive()&&cone(t,2.5,100)&&hasLineOfSight(t)){t.invulnerableTime=0;if(t instanceof org.slavicmyths.poloz.GreatPoloz poloz?org.slavicmyths.poloz.PolozAim.strike(this,poloz,raw):t.hurt(damageSources().mobAttack(this),raw)){cue("alyosha.saber_hit_1");if(level().getGameTime()-lastHit>120)accurate=0;lastHit=level().getGameTime();if(++accurate>=3&&ready("daring")){cooldown("daring",400);daringUntil=level().getGameTime()+80;accurate=0;}}}if(b!=null&&b.held()!=null&&b.held()!=this&&cone(b,2.5,100)&&hasLineOfSight(b)&&(frame(6)||frame(11)))b.rescue(8);}
 private void step(ServerLevel w,SkimBeastEntity b){int t=age();switch(action()){
 case TAUNT->{if(t==11){var k=org.slavicmyths.kalin.KalinParty.commander(this);if(k!=null&&distanceToSqr(k)<196&&hasLineOfSight(k)){k.getPersistentData().putUUID("AlyoshaTaunt",getUUID());k.getPersistentData().putLong("AlyoshaTauntUntil",w.getGameTime()+90);k.setTarget(this);}if(b!=null)b.taunt(this);int count=0;for(var m:w.getEntitiesOfClass(Monster.class,getBoundingBox().inflate(14),e->e.isAlive()&&!isAlliedTo(e)&&hasLineOfSight(e)&&(e.getTarget()==this||e.getTarget()==w.getServer().getPlayerList().getPlayer(owner)))){if(count++>=6)break;m.getPersistentData().putUUID("AlyoshaTaunt",getUUID());m.getPersistentData().putLong("AlyoshaTauntUntil",w.getGameTime()+90);m.setTarget(this);}cue("alyosha.taunt_"+(random.nextBoolean()?1:2));}}
 case DODGE->{if(t>=2&&t<=7&&dodge!=null&&w.noCollision(this,getBoundingBox().move(dodge)))move(MoverType.SELF,dodge);}
 case SABER->{if(frame(3)||frame(9)||frame(14)||frame(18))cue("alyosha.saber_swing_"+(random.nextBoolean()?1:2));if(frame(6)||frame(11))strike(2,b);if(frame(16))strike(2.4F,b);if(frame(19))strike(2.6F,b);}
 case FEINT->{if(t==14){if(b==null||b.action()==SkimAction.RECOVER||b.action()==SkimAction.EXHAUSTED){strike(4,b);if(b!=null)b.fatigue(12);}}}
 case COUNTER->{if(frame(8)){strike(4,b);if(b!=null)b.fatigue(12);cue("alyosha.counter");}}
 case BOW->{if((t==11||t==17||t==23)&&getTarget()!=null&&hasLineOfSight(getTarget())&&edge(getTarget())<=18){var arrow=new AlyoshaArrow(w,this);var at=(getTarget() instanceof org.slavicmyths.poloz.GreatPoloz?org.slavicmyths.poloz.PolozAim.point(this,getTarget()):getTarget().getEyePosition()).subtract(arrow.position());arrow.shoot(at.x,at.y+at.horizontalDistance()*.04,at.z,2,1);arrow.pickup=net.minecraft.world.entity.projectile.AbstractArrow.Pickup.DISALLOWED;w.addFreshEntity(arrow);cue("alyosha.arrow_release");}}
 default->{}
 }}
 public void incomingHit(){accurate=0;daringUntil=0;}
 @Override public void die(DamageSource s){HeroCalls.defeated(this);if(owner!=null&&level() instanceof ServerLevel w){HeroCalls.get(w).alyosha.remove(owner,getUUID());HeroCalls.get(w).setDirty();}super.die(s);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(owner!=null)n.putUUID("AlyoshaOwner",owner);if(arena!=null)n.putUUID("AlyoshaArena",arena);n.putBoolean("LastStand",lastStand);n.putBoolean("Intercepted",intercepted);n.putLong("DaringUntil",daringUntil);n.putInt("BowTicks",bowTicks);n.putInt("CombatTicks",totalCombat);}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);if(n.hasUUID("AlyoshaOwner"))owner=n.getUUID("AlyoshaOwner");if(n.hasUUID("AlyoshaArena"))arena=n.getUUID("AlyoshaArena");lastStand=n.getBoolean("LastStand");intercepted=n.getBoolean("Intercepted");daringUntil=n.getLong("DaringUntil");bowTicks=n.getInt("BowTicks");totalCombat=n.getInt("CombatTicks");entityData.set(RECOVERING,lastStand);if(lastStand)begin(SkimAction.REST);}
}
